$ErrorActionPreference = 'Stop'
Set-StrictMode -Version Latest

$root = (Get-Location).Path
if (-not (Test-Path (Join-Path $root 'pubspec.yaml'))) {
    throw 'Run this script from the almustafa-connect-erp project root.'
}

$utf8 = New-Object System.Text.UTF8Encoding($false)
$stamp = Get-Date -Format 'yyyyMMdd_HHmmss'
$backupRoot = Join-Path (Split-Path $root -Parent) "almustafa-connect-erp_backups/access_control_phase2_$stamp"

function Read-ProjectFile {
    param([Parameter(Mandatory = $true)][string]$RelativePath)

    $path = Join-Path $root $RelativePath
    if (-not (Test-Path $path)) {
        throw "Required file not found: $RelativePath"
    }

    return [IO.File]::ReadAllText($path).Replace("`r`n", "`n")
}

function Write-ProjectFile {
    param(
        [Parameter(Mandatory = $true)][string]$RelativePath,
        [Parameter(Mandatory = $true)][string]$Content
    )

    $path = Join-Path $root $RelativePath
    New-Item -ItemType Directory -Path (Split-Path $path -Parent) -Force | Out-Null
    [IO.File]::WriteAllText($path, $Content, $utf8)
    Write-Host "Created/updated: $RelativePath" -ForegroundColor Green
}

function Backup-ProjectFile {
    param([Parameter(Mandatory = $true)][string]$RelativePath)

    $source = Join-Path $root $RelativePath
    if (-not (Test-Path $source)) { return }

    $destination = Join-Path $backupRoot $RelativePath
    New-Item -ItemType Directory -Path (Split-Path $destination -Parent) -Force | Out-Null
    Copy-Item $source $destination -Force
}

function Add-Import {
    param(
        [Parameter(Mandatory = $true)][string]$Content,
        [Parameter(Mandatory = $true)][string]$ImportLine
    )

    if ($Content.Contains($ImportLine)) {
        return $Content
    }

    $matches = [regex]::Matches(
        $Content,
        "(?m)^import\s+['""].+?['""];\s*$"
    )

    if ($matches.Count -eq 0) {
        throw "Import block not found: $ImportLine"
    }

    $last = $matches[$matches.Count - 1]

    return $Content.Insert(
        $last.Index + $last.Length,
        "`n$ImportLine"
    )
}

function Insert-BeforeFirst {
    param(
        [Parameter(Mandatory = $true)][string]$Content,
        [Parameter(Mandatory = $true)][string]$Marker,
        [Parameter(Mandatory = $true)][string[]]$Patterns,
        [Parameter(Mandatory = $true)][string]$Block
    )

    if ($Content.Contains($Marker)) {
        return $Content
    }

    foreach ($pattern in $Patterns) {
        $match = [regex]::Match($Content, $pattern)
        if ($match.Success) {
            return $Content.Insert($match.Index, $Block)
        }
    }

    throw "Registration anchor not found: $Marker"
}

$payloads = @{
    'lib/features/access_control/domain/entities/user_role_assignment_entity.dart' = ''
    'lib/features/access_control/data/models/user_role_assignment_model.dart' = ''
    'lib/features/access_control/domain/repositories/user_role_assignment_repository.dart' = ''
    'lib/features/access_control/data/repositories/user_role_assignment_repository_impl.dart' = ''
    'lib/features/access_control/presentation/bloc/user_role_assignment_bloc.dart' = ''
    'lib/features/access_control/presentation/pages/user_role_assignment_form_page.dart' = ''
    'lib/features/access_control/presentation/pages/user_role_assignments_page.dart' = ''
}
$firestorePaths = 'lib/core/constants/firestore_paths.dart'
$serviceLocator = 'lib/core/di/service_locator.dart'
$rolesPage = 'lib/features/access_control/presentation/pages/roles_permissions_page.dart'

foreach ($relativePath in (@(
    $firestorePaths,
    $serviceLocator,
    $rolesPage
) + $payloads.Keys)) {
    Backup-ProjectFile -RelativePath $relativePath
}

foreach ($item in $payloads.GetEnumerator()) {
    $text = [Text.Encoding]::UTF8.GetString(
        [Convert]::FromBase64String($item.Value)
    )

    Write-ProjectFile `
        -RelativePath $item.Key `
        -Content $text
}

# Firestore collection path.
$content = Read-ProjectFile -RelativePath $firestorePaths

if (-not $content.Contains(
    'static const String userRoleAssignments'
)) {
    $lastBrace = $content.LastIndexOf('}')

    if ($lastBrace -lt 0) {
        throw 'FirestorePaths closing brace not found.'
    }

    $content = $content.Insert(
        $lastBrace,
        "  static const String userRoleAssignments = 'user_roles';`n"
    )
}

Write-ProjectFile -RelativePath $firestorePaths -Content $content

# Service locator.
$content = Read-ProjectFile -RelativePath $serviceLocator

foreach ($importLine in @(
    "import '../../features/access_control/data/repositories/user_role_assignment_repository_impl.dart';",
    "import '../../features/access_control/domain/repositories/user_role_assignment_repository.dart';",
    "import '../../features/access_control/presentation/bloc/user_role_assignment_bloc.dart';"
)) {
    $content = Add-Import `
        -Content $content `
        -ImportLine $importLine
}

$repositoryRegistration = @'
  sl.registerLazySingleton<UserRoleAssignmentRepository>(
    () => UserRoleAssignmentRepositoryImpl(
      sl<FirebaseFirestoreService>(),
    ),
  );

'@

$content = Insert-BeforeFirst `
    -Content $content `
    -Marker 'registerLazySingleton<UserRoleAssignmentRepository>' `
    -Patterns @(
        '(?m)^\s*sl\.registerLazySingleton<AppRoleRepository>',
        '(?m)^\s*sl\.registerLazySingleton<ParentPortalRepository>',
        '(?m)^\s*sl\.registerLazySingleton<'
    ) `
    -Block $repositoryRegistration

$blocRegistration = @'
  sl.registerFactory<UserRoleAssignmentBloc>(
    () => UserRoleAssignmentBloc(
      sl<UserRoleAssignmentRepository>(),
    ),
  );

'@

$content = Insert-BeforeFirst `
    -Content $content `
    -Marker 'registerFactory<UserRoleAssignmentBloc>' `
    -Patterns @(
        '(?m)^\s*sl\.registerFactory<AppRoleBloc>',
        '(?m)^\s*sl\.registerFactory<ParentPortalBloc>',
        '(?m)^\s*sl\.registerFactory<'
    ) `
    -Block $blocRegistration

Write-ProjectFile `
    -RelativePath $serviceLocator `
    -Content $content

# Roles dashboard: add User Assignments action.
$content = Read-ProjectFile -RelativePath $rolesPage

$content = Add-Import `
    -Content $content `
    -ImportLine "import 'user_role_assignments_page.dart';"

if (-not $content.Contains('const UserRoleAssignmentsPage()')) {
    $oldAppBar = @'
      appBar: AppBar(title: const Text('Roles & Permissions')),
'@

    $newAppBar = @'
      appBar: AppBar(
        title: const Text('Roles & Permissions'),
        actions: [
          TextButton.icon(
            onPressed: () {
              Navigator.of(context).push<void>(
                MaterialPageRoute<void>(
                  builder: (_) =>
                      const UserRoleAssignmentsPage(),
                ),
              );
            },
            icon: const Icon(Icons.manage_accounts_outlined),
            label: const Text('User Assignments'),
          ),
        ],
      ),
'@

    if ($content.Contains($oldAppBar)) {
        $content = $content.Replace($oldAppBar, $newAppBar)
    } else {
        throw 'Roles & Permissions AppBar anchor not found.'
    }
}

Write-ProjectFile -RelativePath $rolesPage -Content $content

$formatFiles = @(
    $firestorePaths,
    $serviceLocator,
    $rolesPage
) + $payloads.Keys

Write-Host ''
Write-Host 'Running dart format...' -ForegroundColor Cyan

& dart format $formatFiles

if ($LASTEXITCODE -ne 0) {
    throw 'dart format failed.'
}

Write-Host ''
Write-Host 'Running flutter analyze...' -ForegroundColor Cyan

& flutter analyze

if ($LASTEXITCODE -ne 0) {
    throw 'flutter analyze found issues. Copy the complete output into ChatGPT.'
}

Write-Host ''
Write-Host 'Roles and Permissions Phase 2 User Assignment completed successfully.' -ForegroundColor Green
Write-Host 'Users can now be linked to active roles using Firebase Auth UID.' -ForegroundColor Cyan
Write-Host "Backup: $backupRoot" -ForegroundColor DarkGray
